#include <stdio.h>

int main() {
    int addr_bits = 16;                 /* 地址码字段占 16 位 */
    long space = 1L << addr_bits;       /* 寻址空间 = 2^addr_bits */
    printf("地址码位数 = %d 位\n", addr_bits);
    printf("寻址空间 = 2^%d = %ld 个存储单元\n", addr_bits, space);
    printf("若按字节编址，可寻址 %ld 字节 = %ld KB\n", space, space / 1024);
    return 0;
}
